def shortest_path(graph, source, target):
    # Convert the graph into a graph representation suitable for Dijkstra's algorithm
    # The graph is represented by a dictionary of dictionaries where:
    # graph[node] is a dictionary of neighboring nodes and their corresponding weights
    # Dijkstra's algorithm uses a priority queue, so node weights are tuples (distance, node)
    # visited is a set to keep track of visited nodes
    visited = set()
    distances = defaultdict(lambda: float('inf'))
    distances[source] = 0
    path = {source: []}

    def relax(node, neighbor, weight):
        if distances[node] + weight < distances[neighbor]:
            distances[neighbor] = distances[node] + weight
            path[neighbor] = path[node] + [neighbor]
            return True
        return False

    def dijkstra():
        priority_queue = [(0, source)]
        while priority_queue:
            current_distance, current_node = heappop(priority_queue)
            if current_node not in visited:
                visited.add(current_node)
                if current_node == target:
                    return current_distance, path[current_node]
                for neighbor, weight in graph[current_node]:
                    if relax(current_node, neighbor, weight):
                        heappush(priority_queue, (current_distance + weight, neighbor))
        return float('inf'), None

    return dijkstra()

