        # If we've found the target, return the path.
        if current_path[-1] == target:
            return (current_cost, current_path)

        # If we've already found a shorter path to the current node, skip it.
        if current_path[-1] in cost_so_far and cost_so_far[current_path[-1]] <= current_cost:
            continue

        # Otherwise, update the cost and path.
