        for neighbor, weight in graph.get(current_path[-1], []):
            next_path = list(current_path)
            next_path.append(neighbor)
            new_cost = current_cost + weight
            if neighbor not in cost_so_far or new_cost < cost_so_far[neighbor]:
                cost_so_far[neighbor] = new_cost
                priority = new_cost, next_path
                heappush(frontier, priority)
                came_from[neighbor] = current_path[-1]

    # If we've exhausted the frontier without finding the target, the target is unreachable.
